{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Niraparib, a fused heteroaromatic drug containing a basic piperidine, has an absolute oral bioavailability of approximately 73% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Flecainide, a basic amine-containing aromatic drug, shows absolute oral bioavailability averaging 70% (range 60-86%) in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Naratriptan, which contains an N-methylpiperidine attached to an indole heteroaromatic, has oral bioavailability of 63% in men and 74% in women, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Sertindole, a lipophilic piperidine-containing antipsychotic, is well absorbed orally with a bioavailability of approximately 74%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Risdiplam, a heteroaromatic drug with a piperazine and high oral bioavailability due to complete absorption and negligible first-pass effects, supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Tasimelteon has an absolute oral bioavailability of 38.33% (90% CI 26.94-54.33%), confirming that even moderately extracted lipophilic drugs exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Didanosine shows low oral bioavailability (19% in children), but this is driven by acid lability and extensive first-pass metabolism in a polar nucleoside, mechanisms not shared by the lipophilic, basic, acid-stable query; therefore it does not support a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic fused pyrazino-benzazepine with a basic piperidine nitrogen. Multiple high-transfer analogues with similar basic amine/heteroaromatic structures show absolute oral bioavailability well above 20% (niraparib 73%, flecainide 70-95%, naratriptan 63-74%, sertindole 74-75%, risdiplam high, tasimelteon 38%). The only low-F analogue, didanosine, owes its poor bioavailability to acid lability and first-pass metabolism that are absent in the query. Therefore high oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "Some supporting records are not explicitly absolute bioavailability determinations.",
    "The didanosine low-F mechanism is not transferable, but no direct query-specific data are available to exclude other first-pass liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

